     ws_send(sock,{'type':'subscribed' if x['type']=='subscribe' else 'resumed','channel_id':cid,'head_event_id':c.execute('SELECT COALESCE(n,0) n FROM seq WHERE channel_id=?',(cid,)).fetchone()['n']})
